import { useId, type ComponentProps, type ReactNode } from "react";
import { CopyButton } from "./copy-button";
import { cn } from "./utils";
import { codeTokens } from "./foundation/code-tokens";

type CodeBlockProps = Omit<
    ComponentProps<"figure">, "children" | "aria-labelledby"
> & {
    label: string;
    code: string;
    language?: string;
    wrap?: boolean;
    copyable?: boolean;
    showLineNumbers?: boolean;
    syntaxHighlight?: boolean;
};

function codeLines(code: string, language: string | undefined, numbered: boolean, highlight: boolean): ReactNode {
    const tokens = highlight ? codeTokens(code, language) : [];
    let start = 0;
    let tokenIndex = 0;
    return code.split("\n").map((line, index, lines) => {
        const end = start + line.length;
        while (tokens[tokenIndex] && tokens[tokenIndex]!.to <= start) tokenIndex++;
        const pieces: ReactNode[] = [];
        let offset = 0;
        for (let i = tokenIndex; tokens[i] && tokens[i]!.from < end; i++) {
            const token = tokens[i]!;
            const from = Math.max(start, token.from) - start;
            const to = Math.min(end, token.to) - start;
            pieces.push(line.slice(offset, from));
            pieces.push(<span key={token.from} data-code-kind={token.kind} style={{ color: `var(--code-${token.kind}, var(--${token.kind === "comment" ? "muted" : token.kind === "string" ? "success" : token.kind === "number" ? "warning" : "accent"}))` }}>{line.slice(from, to)}</span>);
            offset = to;
        }
        pieces.push(line.slice(offset));
        start = end + 1;
        return <span key={index} data-slot="code-line">
            {numbered && <span aria-hidden="true" data-slot="line-number" className="mr-4 inline-block w-8 select-none text-right text-muted">{index + 1}</span>}
            {pieces}{index < lines.length - 1 ? "\n" : null}
        </span>;
    });
}

function CodeBlock({
    label,
    code,
    language,
    wrap = false,
    copyable = true,
    showLineNumbers = false,
    syntaxHighlight = false,
    className,
    ...props
}: CodeBlockProps) {
    const labelId = useId();

    if (typeof label !== "string" || !label.trim()) {
        throw new Error("CodeBlock requires a label.");
    }
    if (typeof code !== "string") {
        throw new TypeError("CodeBlock code must be a string.");
    }
    if (language !== undefined && (
        typeof language !== "string" || !language.trim()
    )) {
        throw new Error("CodeBlock language must not be empty.");
    }

    return (
        <figure {...props} aria-labelledby={labelId}
            data-ui="code-block" data-surface="panel"
            className={cn(
                "m-0 min-w-0 overflow-hidden rounded-sm border " +
                "border-border bg-surface",
                className,
            )}>
            <figcaption id={labelId} data-slot="surface-header"
                className={
                    "flex min-w-0 items-center gap-2 border-b " +
                    "border-border bg-surface-subtle px-[var(--space-3)] " +
                    "py-[var(--space-1)] text-sm text-foreground"
                }>
                <span data-slot="surface-title" className="min-w-0 flex-1 truncate font-medium">
                    {label}
                </span>
                {language && (
                    <span data-slot="surface-meta" className="text-xs text-muted">{language}</span>
                )}
                {copyable && (
                    <CopyButton value={code} label={`${label} 복사`}
                        appearance="text" disabled={!code}
                        successMessage="코드를 복사했습니다"
                        errorMessage="코드를 복사하지 못했습니다" />
                )}
            </figcaption>
            <pre data-slot="reading-plane" tabIndex={0} aria-label={`${label} 코드`}
                className={cn(
                    "m-0 max-w-full overflow-auto p-[var(--space-4)] " +
                    "text-xs leading-6 text-foreground",
                    wrap ? "whitespace-pre-wrap break-words" :
                        "whitespace-pre",
                )}>
                <code>{!showLineNumbers && !syntaxHighlight ? code : codeLines(code, language, showLineNumbers, syntaxHighlight)}</code>
            </pre>
        </figure>
    );
}

export { CodeBlock };
export type { CodeBlockProps };

export type CodeToken = {
    from: number;
    to: number;
    kind: "comment" | "string" | "number" | "keyword";
};

/** Small lexical accents, not a compiler or a complete language grammar. */
export function codeTokens(code: string, language = ""): CodeToken[] {
    const name = language.toLowerCase().trim();
    if (!/^(javascript|typescript|jsx|tsx|js|ts|json|python|py|kotlin|kt|java|sql|bash|sh|shell|css)$/.test(name) || code.length > 100_000) return [];
    const hashComments = /^(python|py|bash|sh|shell)$/.test(name);
    const keywords = "async|await|const|let|var|function|return|if|else|for|while|class|new|import|export|from|default|throw|try|catch|finally|true|false|null|undefined|def|in|with|as|None|True|False|val|fun|override|private|public|void|int|String|select|from|where|and|or|not|insert|into|values|update|set|delete|create|table|join|on|order|by|limit";
    const pattern = new RegExp(
        '/\\*[\\s\\S]*?\\*/|//[^\\n]*|' + (hashComments ? '#[^\\n]*|' : '') +
        '"(?:\\\\.|[^"\\\\])*"|\'(?:\\\\.|[^\'\\\\])*\'|`(?:\\\\.|[^`\\\\])*`|\\b\\d+(?:\\.\\d+)?\\b|\\b(?:' + keywords + ')\\b',
        "gi",
    );
    return Array.from(code.matchAll(pattern), match => ({
        from: match.index,
        to: match.index + match[0].length,
        kind: /^(\/\/|\/\*|#)/.test(match[0]) ? "comment" :
            /^["'`]/.test(match[0]) ? "string" : /^\d/.test(match[0]) ? "number" : "keyword",
    }));
}
